package com.craftmarket.controller;

import com.craftmarket.entity.User;
import com.craftmarket.service.AuthService;
import com.craftmarket.utils.Result;
import com.craftmarket.vo.JwtResponse;
import com.craftmarket.vo.UserVO;
import io.swagger.v3.oas.annotations.Operation;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.constraints.NotBlank;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

/**
 * 认证控制器
 */
@RestController
@RequestMapping("/api/auth")
@Tag(name = "认证管理", description = "用户登录、注册、token管理接口")
public class AuthController {

    @Autowired
    private AuthService authService;

    @PostMapping("/login")
    @Operation(summary = "用户登录", description = "根据用户名和密码获取JWT令牌")
    public Result<JwtResponse> login(@NotBlank @RequestParam String username,
                                   @NotBlank @RequestParam String password) {
        try {
            String token = authService.login(username, password);
            User user = authService.getUserFromToken(token);
            UserVO userVO = new UserVO(user.getId(), user.getUsername(), user.getRole().name());
            return Result.success(new JwtResponse(token, userVO));
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }

    @PostMapping("/register")
    @Operation(summary = "用户注册", description = "新用户注册（摊主注册）")
    public Result<String> register(@NotBlank @RequestParam String username,
                                 @NotBlank @RequestParam String password,
                                 @NotBlank @RequestParam String phone,
                                 @NotBlank @RequestParam String name,
                                 @NotBlank @RequestParam String businessType) {
        try {
            boolean success = authService.register(username, password, phone, name, businessType);
            return success ? Result.success("注册成功") : Result.badRequest("注册失败");
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }

    @PostMapping("/refresh-token")
    @Operation(summary = "刷新令牌", description = "使用原有令牌刷新获取新的JWT令牌")
    public Result<JwtResponse> refreshToken(@NotBlank @RequestParam String token) {
        try {
            String newToken = authService.refreshToken(token);
            User user = authService.getUserFromToken(newToken);
            UserVO userVO = new UserVO(user.getId(), user.getUsername(), user.getRole().name());
            return Result.success(new JwtResponse(newToken, userVO));
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }

    @PostMapping("/validate")
    @Operation(summary = "验证令牌", description = "验证JWT令牌是否有效")
    public Result<String> validateToken(@NotBlank @RequestParam String token) {
        try {
            boolean valid = authService.validateToken(token);
            return valid ? Result.success("令牌有效") : Result.badRequest("令牌无效");
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }

    @PostMapping("/logout")
    @Operation(summary = "用户登出", description = "用户登出（JWT无状态，主要供客户端清除令牌）")
    @PreAuthorize("isAuthenticated()")
    public Result<String> logout(@RequestParam String token) {
        try {
            boolean success = authService.logout(token);
            return success ? Result.success("登出成功") : Result.badRequest("登出失败");
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }

    @GetMapping("/current-user")
    @Operation(summary = "获取当前用户信息", description = "根据JWT令牌获取当前登录用户信息")
    @PreAuthorize("isAuthenticated()")
    public Result<UserVO> getCurrentUser() {
        try {
            String token = ((ServletRequestAttributes) RequestContextHolder.currentRequestAttributes()).getRequest().getHeader("Authorization");
            if (token != null && token.startsWith("Bearer ")) {
                token = token.substring(7);
            }

            User user = authService.getUserFromToken(token);
            UserVO userVO = new UserVO(user.getId(), user.getUsername(), user.getRole().name());
            return Result.success(userVO);
        } catch (Exception e) {
            return Result.badRequest(e.getMessage());
        }
    }
}

package com.craftmarket.controller;

import com.craftmarket.entity.MarketEvent;
import com.craftmarket.service.MarketEventService;
import com.craftmarket.utils.Result;
import com.craftmarket.enums.MarketEventStatus;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/market-events")
@CrossOrigin(origins = "*")
public class MarketEventController {

    @Autowired
    private MarketEventService marketEventService;

    @PostMapping
    public Result<?> createMarketEvent(@RequestBody MarketEvent marketEvent) {
        if (marketEventService.saveMarketEvent(marketEvent)) {
            return Result.success("活动创建成功");
        }
        return Result.error("活动创建失败");
    }

    @GetMapping("/{id}")
    public Result<?> getMarketEventById(@PathVariable Long id) {
        return Result.success(marketEventService.getMarketEventById(id));
    }

    @PutMapping("/{id}")
    public Result<?> updateMarketEvent(@PathVariable Long id, @RequestBody MarketEvent marketEvent) {
        marketEvent.setId(id);
        if (marketEventService.updateMarketEvent(marketEvent)) {
            return Result.success("活动更新成功");
        }
        return Result.error("活动更新失败");
    }

    @GetMapping
    public Result<?> getAllMarketEvents(@RequestParam(defaultValue = "1") int page,
                                      @RequestParam(defaultValue = "10") int size,
                                      @RequestParam(required = false) String eventName,
                                      @RequestParam(required = false) String status) {
        MarketEvent.MarketEventStatus statusEnum = status != null ? MarketEvent.MarketEventStatus.valueOf(status) : null;
        Page<MarketEvent> events = marketEventService.getMarketEventsPage(page, size, eventName, statusEnum);
        return Result.success(events);
    }

    @GetMapping("/active")
    public Result<?> getActiveMarketEvents(@RequestParam(defaultValue = "1") int page,
                                          @RequestParam(defaultValue = "10") int size) {
        Page<MarketEvent> pageObj = new Page<>(page, size);
        Page<MarketEvent> events = marketEventService.getMarketEventsByStatus(MarketEvent.MarketEventStatus.ACTIVE, pageObj);
        return Result.success(events);
    }

    @GetMapping("/upcoming")
    public Result<?> getUpcomingMarketEvents(@RequestParam(defaultValue = "1") int page,
                                           @RequestParam(defaultValue = "10") int size) {
        // 这里可以根据实际需求过滤未来的活动
        return Result.success(new Page<>());
    }

    @PutMapping("/{id}/publish")
    public Result<?> publishMarketEvent(@PathVariable Long id) {
        if (marketEventService.updateEventStatus(id, MarketEventStatus.ACTIVE)) {
            return Result.success("活动发布成功");
        }
        return Result.error("活动发布失败");
    }

    @PutMapping("/{id}/cancel")
    public Result<?> cancelMarketEvent(@PathVariable Long id) {
        if (marketEventService.updateEventStatus(id, MarketEventStatus.CANCELLED)) {
            return Result.success("活动取消成功");
        }
        return Result.error("活动取消失败");
    }
}

